from pathlib import Path
import json,base64
R=Path(__file__).resolve().parents[1]
def uri(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
assets={k:uri(R/'exports'/f'{name}.png') for k,name in [('atlas','battery-atlas-32'),('icon16','battery-item-16'),('icon32','battery-item-32')]}
assets.update({k:uri(R/'review'/f'battery-{k}.png') for k in ['empty','half','full','back']});assets['node']=uri(R/'review/battery-node-fit-simulation.png');assets['socket']=uri(R/'review/battery-socket-fit-simulation.png')
for n in (16,32):assets['status'+str(n)]=uri(R/'references'/f'battery-full-{n}.png')
html='''<!DOCTYPE html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wildcraft 有限电池 · v01 审稿</title><style>*{box-sizing:border-box}body{margin:0;background:#111b17;color:#e3e8d9;font:15px/1.6 system-ui,-apple-system,sans-serif}main{max-width:1250px;margin:auto;padding:28px}h1{font-size:28px;margin:8px 0}h2{font-size:20px}.kicker{color:#d6b77d;font-size:12px;letter-spacing:2px}.muted{color:#a4b7a6}.controls{display:flex;gap:16px;flex-wrap:wrap;padding:18px;background:#202d25;border-radius:8px;margin:20px 0}label{display:flex;gap:8px;align-items:center}input,select{font:inherit}select{background:#304331;color:#e3e8d9;padding:6px;border:1px solid #617b57}:focus-visible{outline:3px solid #d6b77d;outline-offset:3px}.live{display:flex;flex-wrap:wrap;gap:24px;padding:20px;background:#0a100d;overflow:auto}canvas{image-rendering:pixelated;display:block;max-width:none}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}.card{background:#202d25;padding:18px;border:1px solid #35473a}.card img{width:100%;height:auto}.card h3{margin:0 0 12px}.note{font-size:13px;color:#b6c4ae}footer{margin-top:24px;padding:20px 0;border-top:1px solid #35473a;color:#a6b79f;font-size:13px}</style><main><div class="kicker">WILDCRAFT · F04-01 · v01</div><h1>有限电池 · 同一外壳，真实余量</h1><p class="muted">金属外框、铜接点、三格红石能量窗。此页为可旋转实际几何的审稿模型与实际模型渲染；未接入游戏。</p><div class="controls"><label>电量<input id="energy" type="range" min="0" max="1000" value="500"><output id="energy-value">500 / 1000</output></label><label>方向<input id="yaw" type="range" min="-180" max="180" value="-25"></label><label>俯仰<input id="pitch" type="range" min="-60" max="60" value="18"></label><label>图标显示<select id="scale"><option>1</option><option>2</option><option selected>4</option><option>8</option></select></label></div><section class="live"><canvas id="model" role="img" aria-label="实际电池几何的可旋转模拟"></canvas><div><h2>原生物品图</h2><p class="note">32×32 与 16×16，独立设计</p><canvas id="icon32" role="img" aria-label="32像素电池物品图"></canvas><br><canvas id="icon16" role="img" aria-label="16像素电池物品图"></canvas><p id="status" aria-live="polite"></p><p class="note">窗口从下到上填充；精确值仍由原版物品电量条与提示读取。<br>此处为程序遮罩演示，尚未替换游戏物品渲染。</p></div></section><h2>实际模型渲染 · 相同尺寸与外壳</h2><div class="grid"><article class="card"><h3>空电 · 0 / 1000</h3><img id="render-empty" alt="同一电池空电模型"><p class="note">三格暗窗可辨，外壳和接点不变化。</p></article><article class="card"><h3>部分 · 500 / 1000</h3><img id="render-half" alt="同一电池半电模型"><p class="note">下格满，中格半，上格空。</p></article><article class="card"><h3>满电 · 1000 / 1000</h3><img id="render-full" alt="同一电池满电模型"><p class="note">三格填满，不追加全屏发光或新Shader。</p></article></div><h2>接口与尺寸示意</h2><div class="grid"><article class="card"><h3>背面接点</h3><img id="render-back" alt="平背与铜接点"><p class="note">平背与铜点用于设备视觉对齐，不增加新玩法接口。</p></article><article class="card"><h3>机械节点</h3><img id="render-node" alt="现机械尺寸灰盒节点叠放模拟"><p class="note">灰盒采用现主体尺寸；不是已完成机械美术或实机截图。</p></article><article class="card"><h3>插座参照</h3><img id="render-socket" alt="同尺度电池插座参照"><p class="note">仅说明同一电池的容纳关系，充电器外观在后续单独制作。</p></article></div><footer>本项草稿待审。实际几何16方盒＋3动态窗口平面；原生32px材质图集。动态窗口显示依赖真实电量，保留容量1000和现物品数据。旧已采用电量HUD图标保持原稿，下一项再做其显示映射。Studio光照、机械／插座灰盒和交互软件渲染均不等于游戏实测。</footer></main><script>__JS__</script><script>
const B=WildcraftBatteryPreview,G=__GEO__,REG=__REG__,urls=__ASSETS__,imgs={};
function update(){const e=Number(document.getElementById('energy').value),yaw=Number(document.getElementById('yaw').value),pitch=Number(document.getElementById('pitch').value),scale=Number(document.getElementById('scale').value);window.lastModel=B.drawModel(document.getElementById('model'),imgs.atlas,G,e,yaw,pitch);const icons=[];for(const n of [32,16]){const cv=document.getElementById('icon'+n);cv.width=n;cv.height=n;cv.style.width=n*scale+'px';cv.style.height=n*scale+'px';icons.push(B.drawIcon(cv.getContext('2d'),imgs['icon'+n],REG.regions[String(n)],n,e));}document.getElementById('energy-value').textContent=e+' / 1000';document.getElementById('status').textContent='余量 '+Math.round(e/10)+'% · '+(e===0?'空电':e===1000?'满电':'部分电量');window.lastIcons=icons;}
for(const id of ['energy','yaw','pitch'])document.getElementById(id).oninput=update;document.getElementById('scale').onchange=update;
window.reviewReady=false;Promise.all(Object.entries(urls).map(([k,v])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{imgs[k]=im;resolve();};im.onerror=reject;im.src=v;}))).then(()=>{for(const k of ['empty','half','full','back','node','socket'])document.getElementById('render-'+k).src=urls[k];update();window.reviewReady=true;});
</script></html>'''
html=html.replace('__JS__',(R/'source/battery-preview.js').read_text()).replace('__GEO__',(R/'source/geometry-and-uv.json').read_text()).replace('__REG__',(R/'exports/battery-item-energy-regions.json').read_text()).replace('__ASSETS__',json.dumps(assets))
(R/'review/preview.html').write_text(html);print('实际几何＋动态遮罩交互审稿页已生成。')
